"""catalogue.json, generated by videoauto itself: python -m videoauto.occ_catalogue [--refresh]

Nobody copies a script by hand any more. When catalogue.json is missing, or was dumped from a
different OpenChatCut than the one configured (a catalogue copied from another machine makes
Remotion die with exit 1 in readFile), videoauto:
  1. copies openchatcut/dump-catalogue.mts into <OpenChatCut>/scripts/ (under a videoauto- name),
  2. runs it with OpenChatCut's own Node + tsx, passing videoauto's bundled Vietnamese font
     verdicts (openchatcut/vi-font-review.json, vi-stack-review.json) so vi_ok is set on a fresh
     machine without re-running the 6-minute render audit,
  3. removes the copied script again and stamps catalogue.json with a fingerprint of the inputs.

Two stacked-diacritic verdict files are bundled, because the result depends on OpenChatCut's font
loader: vi-stack-review.json for upstream OpenChatCut (Windows Georgia draws Ố Ầ Ắ … with a detached
mark: 131 vi_ok), and vi-stack-review.georgia-fix.json for an OpenChatCut with the Georgia/Gelasio
fix (src/fonts/georgiaVietnamese.ts, branch videoauto of the fork: 134 vi_ok). The one matching the
configured OpenChatCut is used.

The fingerprint hashes what the dump reads in OpenChatCut (template JSON, the effect/transition
sources, package.json, the font fix if present) plus videoauto's dump script and review files.
Any change -> regenerate.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import logging
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

from .errors import UserError

log = logging.getLogger("videoauto")

BUNDLE = Path(__file__).resolve().parent.parent / "openchatcut"
SCRIPT = "dump-catalogue.mts"
REVIEWS = ("vi-font-review.json", "vi-stack-review.json", "vi-stack-review.georgia-fix.json")
GEORGIA_FIX = "src/fonts/georgiaVietnamese.ts"
COPIED_NAME = "videoauto-dump-catalogue.mts"
# What scripts/dump-catalogue.mts reads in the OpenChatCut repo (directly or through imports).
OCC_INPUTS = ("assets/templates", "src/gl", "src/editor/types.ts", "src/types.ts", "package.json", GEORGIA_FIX,
              "src/fonts/projectFonts.ts")
STAMP = "videoauto"


def _hash_tree(h, root: Path, rel: str) -> None:
    p = root / rel
    files = sorted(x for x in p.rglob("*") if x.is_file()) if p.is_dir() else ([p] if p.is_file() else [])
    h.update(f"<{rel}:{len(files)}>".encode())
    for f in files:
        h.update(f.relative_to(root).as_posix().encode())
        # line endings normalised: a git checkout with core.autocrlf must not look like a new version
        h.update(hashlib.sha256(f.read_bytes().replace(b"\r\n", b"\n")).digest())


def fingerprint(repo: Path, bundle: Path = BUNDLE) -> str:
    """sha256 of every input of the dump: OpenChatCut's side and videoauto's side."""
    h = hashlib.sha256()
    for rel in OCC_INPUTS:
        _hash_tree(h, repo, rel)
    for name in (SCRIPT, *REVIEWS):
        _hash_tree(h, bundle, name)
    return h.hexdigest()


def git_head(repo: Path) -> str | None:
    try:
        r = subprocess.run(["git", "-C", str(repo), "rev-parse", "--short", "HEAD"],
                           capture_output=True, text=True, timeout=10)
    except (OSError, subprocess.TimeoutExpired):
        return None
    return r.stdout.strip() or None if r.returncode == 0 else None


def stamp_of(path: Path) -> dict | None:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    s = data.get(STAMP) if isinstance(data, dict) else None
    return s if isinstance(s, dict) else None


def stack_review_name(repo: Path) -> str:
    """The stacked-diacritic verdicts that match this OpenChatCut's font loader."""
    return "vi-stack-review.georgia-fix.json" if (repo / GEORGIA_FIX).is_file() else "vi-stack-review.json"


def why_stale(path: Path, repo: Path, bundle: Path = BUNDLE) -> str | None:
    """None if catalogue.json is current for this OpenChatCut; else why it must be regenerated."""
    if not path.exists():
        return "chưa có catalogue.json"
    st = stamp_of(path)
    if st is None:
        return "catalogue.json không có vân tay của videoauto (tạo thủ công hoặc bởi bản cũ)"
    if st.get("fingerprint") != fingerprint(repo, bundle):
        was = st.get("openchatcut_git") or "?"
        now = git_head(repo) or "?"
        return (f"catalogue.json được tạo từ một bản OpenChatCut khác (lúc đó: {was}, hiện tại: {now}) "
                "hoặc từ kết quả kiểm font khác")
    return None


def summary(path: Path) -> str:
    """One line: the counts the dump printed, including the vi_ok ones."""
    data = json.loads(path.read_text(encoding="utf-8"))
    items = data.get("items") or []
    tpls = [i for i in items if i.get("kind") == "template"]
    ok = [t for t in tpls if t.get("vi_ok") is True]

    def orient(t):
        w, h = t.get("width"), t.get("height")
        if not (isinstance(w, int) and isinstance(h, int)):
            return "?"
        return "1:1" if w == h else ("dọc" if h > w else "ngang")

    by = {k: sum(orient(t) == k for t in ok) for k in ("dọc", "ngang", "1:1")}
    c = data.get("counts") or {}
    return (f"{c.get('effect', '?')} hiệu ứng, {c.get('lut', '?')} LUT, {c.get('transition', '?')} chuyển cảnh, "
            f"{len(tpls)} template; vi_ok (dùng được với chữ tiếng Việt): {len(ok)}/{len(tpls)} "
            f"(dọc {by['dọc']}, ngang {by['ngang']}, vuông {by['1:1']})")


def generate(path: Path, repo: Path, node: str, bundle: Path = BUNDLE, timeout: int = 300) -> None:
    """Dump catalogue.json from this OpenChatCut. Raises UserError with what to do."""
    script = bundle / SCRIPT
    missing = [n for n in (SCRIPT, *REVIEWS) if not (bundle / n).is_file()]
    if missing:
        raise UserError(f"Thiếu tệp đi kèm videoauto: {', '.join(str(bundle / m) for m in missing)}. "
                        "Tải lại videoauto (git pull hoặc clone lại).")
    if not (repo / "scripts").is_dir() or not (repo / "node_modules" / "tsx").exists():
        raise UserError(f"Không tạo được catalogue.json: '{repo}' không phải repo OpenChatCut đã cài "
                        "(thiếu scripts/ hoặc node_modules/tsx). Chạy: python -m videoauto.setup (cài OpenChatCut), "
                        "và kiểm tra openchatcut.repo trong config.yaml.")
    copied = repo / "scripts" / COPIED_NAME
    tmp = path.with_name(path.name + ".tmp")
    path.parent.mkdir(parents=True, exist_ok=True)
    stack = stack_review_name(repo)
    shutil.copyfile(script, copied)
    try:
        with tempfile.TemporaryDirectory(prefix="videoauto_reviews_") as reviews:
            # the dump reads <reviewDir>/vi-font-review.json and vi-stack-review.json
            shutil.copyfile(bundle / "vi-font-review.json", Path(reviews) / "vi-font-review.json")
            shutil.copyfile(bundle / stack, Path(reviews) / "vi-stack-review.json")
            proc = subprocess.run([node, "--import", "tsx", f"scripts/{COPIED_NAME}", str(tmp), reviews],
                                  cwd=repo, capture_output=True, text=True, encoding="utf-8",
                                  errors="replace", timeout=timeout)
    except subprocess.TimeoutExpired:
        raise UserError(f"Tạo catalogue.json quá {timeout}s trong '{repo}'.") from None
    except OSError as e:
        raise UserError(f"Không chạy được Node.js ('{node}') để tạo catalogue.json: {e.strerror or e}.") from None
    finally:
        copied.unlink(missing_ok=True)
    if proc.returncode != 0 or not tmp.is_file():
        tmp.unlink(missing_ok=True)
        tail = " | ".join([ln for ln in (proc.stderr + "\n" + proc.stdout).splitlines() if ln.strip()][-6:])
        raise UserError(f"Tạo catalogue.json từ OpenChatCut thất bại (exit {proc.returncode}): {tail[:600]}")
    data = json.loads(tmp.read_text(encoding="utf-8"))
    data[STAMP] = {"fingerprint": fingerprint(repo, bundle), "openchatcut_repo": str(repo),
                   "openchatcut_git": git_head(repo), "reviews": str(bundle), "stack_review": stack}
    tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    os.replace(tmp, path)


def ensure(path: Path, repo: Path, node: str, bundle: Path = BUNDLE, force: bool = False,
           say=None) -> bool:
    """Regenerate catalogue.json when missing or stale (or force). Returns True if it was written."""
    say = say or log.info
    reason = "yêu cầu tạo lại (--refresh)" if force else why_stale(path, repo, bundle)
    if reason is None:
        return False
    say(f"catalogue: {reason} → tự tạo lại từ OpenChatCut tại {repo} (vài giây)…")
    generate(path, repo, node, bundle)
    say(f"catalogue: đã ghi {path}: {summary(path)}")
    return True


def main(argv: list[str] | None = None) -> int:
    from .brief import load_project_config
    from .cli import guarded, setup_io
    ap = argparse.ArgumentParser(prog="python -m videoauto.occ_catalogue",
                                 description="Tạo (hoặc kiểm tra) catalogue.json từ OpenChatCut.")
    ap.add_argument("--config", type=Path, default=None, help="config.yaml (mặc định: thư mục hiện tại)")
    ap.add_argument("--refresh", action="store_true", help="tạo lại kể cả khi còn khớp")
    args = ap.parse_args(argv)
    setup_io(True)

    def run() -> int:
        pcfg = load_project_config(args.config)
        if not ensure(pcfg.catalogue, pcfg.occ.repo, pcfg.occ.node, force=args.refresh, say=print):
            print(f"catalogue: {pcfg.catalogue} khớp với OpenChatCut hiện tại: {summary(pcfg.catalogue)}")
        return 0

    return guarded(run, False)


if __name__ == "__main__":
    sys.exit(main())
